import socket, struct, os
print(open("/etc/resolv.conf").read().replace("\n"," | "))
for srv in ("10.0.2.3", "8.8.8.8"):
    q = struct.pack(">HHHHHH", 0x1234, 0x0100, 1, 0, 0, 0) + b"".join(bytes([len(p)]) + p.encode() for p in "deb.debian.org".split(".")) + b"\0\0\1\0\1"
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(3)
    try:
        s.sendto(q, (srv, 53)); d = s.recv(512); print(srv, "answered", len(d))
    except Exception as e:
        print(srv, "error", repr(e))
try:
    print("getaddrinfo", socket.getaddrinfo("deb.debian.org", 80)[0][4])
except Exception as e:
    print("getaddrinfo error", repr(e))
try:
    c = socket.create_connection(("151.101.2.132", 80), 5); print("tcp ok"); c.close()
except Exception as e:
    print("tcp error", repr(e))

EOF
